/* ---- indexes + helpers (active rows only) ---- */
(function(D){
  var all={}, byId={}, kids={}, rootsByTab={}, tabById={};
  D.shrubs.forEach(function(r){
    all[r[0]]={shrubId:r[0], parentId:r[1], label:r[2], order:r[3],
               disabled:!!r[4], payload:D.payloads[r[0]]||null};
  });
  /* a row is active if it isn't disabled and no ancestor is disabled */
  function active(o){
    var seen=0;
    while(o && seen++<50){ if(o.disabled) return false; o=(o.parentId==null?null:all[o.parentId]); }
    return true;
  }
  var childCount={};
  Object.keys(all).forEach(function(k){ var o=all[k]; if(o.parentId!=null) childCount[o.parentId]=(childCount[o.parentId]||0)+1; });

  Object.keys(all).forEach(function(k){
    var o=all[k];
    if(!active(o)) return;
    /* drop blank-label spacer leaves; keep blank labels that carry children */
    if(!String(o.label).trim() && !childCount[o.shrubId]) return;
    byId[o.shrubId]=o;
  });
  Object.keys(byId).forEach(function(k){
    var o=byId[k], p=(o.parentId==null?'__root__':o.parentId);
    (kids[p]=kids[p]||[]).push(o);
  });
  Object.keys(kids).forEach(function(k){
    kids[k].sort(function(a,b){ return (a.order-b.order) || String(a.label).localeCompare(String(b.label)); });
  });
  D.tabs.forEach(function(t){ if(!t.disabled) tabById[t.tabId]=t; });
  D.shrubTab.forEach(function(p){ if(byId[p[0]]&&tabById[p[1]]) (rootsByTab[p[1]]=rootsByTab[p[1]]||[]).push(p[0]); });

  D.getShrub      = function(id){ return byId[id]||null; };
  D.getChildren   = function(parentId){ return (kids[parentId==null?'__root__':parentId]||[]).slice(); };
  D.hasChildren   = function(id){ return !!(kids[id]&&kids[id].length); };
  D.getTab        = function(tabId){ return tabById[tabId]||null; };
  D.getRootsForTab= function(tabId){
    return (rootsByTab[tabId]||[]).map(function(id){ return byId[id]; }).filter(Boolean)
      .sort(function(a,b){ return (a.order-b.order) || String(a.label).localeCompare(String(b.label)); });
  };
  D.usableTabs = function(){
    return Object.keys(rootsByTab).map(function(id){ return tabById[id]; }).filter(Boolean);
  };
  D.contentsFor = function(id){
    var s=byId[id]; if(!s) return '';
    if(s.payload && s.payload.contents){
      var c=s.payload.contents; return Array.isArray(c)?c.join(' '):String(c);
    }
    return s.label;
  };
  D.stats = {total:D.shrubs.length, active:Object.keys(byId).length};
})(window.ICA_DATA);
